/**
 * Single-value choice from a closed list (`design/components/select.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/select.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { createMemo, createUniqueId, mergeProps, onCleanup, onMount, type JSX } from 'solid-js'
import { Portal } from 'solid-js/web'

import * as zag from '@zag-js/select'
import { normalizeProps } from '@zag-js/solid'

import {
  Each,
  Icon,
  afresh,
  agentMember,
  claimSlot,
  createDerived,
  elementRef,
  followHighlight,
  mergeParts,
  returnFocus,
  scope,
  useDirection,
  useMachine,
  useMediaQuery,
  watchEffect,
  type Defaults,
} from '@polymorph/solid'
import { usePresence } from '@polymorph/solid/motion'
import styles from '@polymorph/recipes/controls/select.module.css'
import sheet from '@polymorph/recipes/overlays/sheet.module.css'

export interface SelectOption {
  value: string
  label: string
  description?: string
  disabled?: boolean
}

export interface SelectOptionGroup {
  label: string
  options: SelectOption[]
}

export interface SelectProps {
  'aria-describedby'?: string
  /**
   * Wired by FormField; set directly only when there is no visible label.
   */
  'aria-label'?: string
  /**
   * Names the field from a label elsewhere on the page, such as `SettingsRow`'s row label, which
   * is one label for a whole row rather than one per control.
   */
  'aria-labelledby'?: string
  'aria-required'?: boolean
  /**
   * Opens on mount. For galleries and tests; screens let the user open it.
   */
  defaultOpen?: boolean
  defaultValue?: string | null
  disabled?: boolean
  /**
   * Labels a selectable empty choice, always rendered as the **first** item. Choosing it reports
   * `null`. The trigger then shows this label as a real value, because "All" is a chosen state,
   * not a missing value.
   */
  emptyOption?: string
  id?: string
  invalid?: boolean
  name?: string
  onChange?: (value: string | null) => void
  /**
   * Flat, grouped, or mixed. `emptyOption` stays first and belongs to no group.
   */
  options: (SelectOption | SelectOptionGroup)[]
  /**
   * Muted, and shown only until there is a value. Cannot be combined with `emptyOption`.
   */
  placeholder?: string
  /**
   * `'auto'` shows the panel as a sheet below `30rem` (the conventions' sheet presentation, the
   * usual phone pattern for choosing from a list). `'popover'` keeps the popper at every width,
   * for the rare pointer-first case that needs precision. There is no always-sheet value,
   * because a bottom sheet on a wide pointer screen is the wrong pattern (`docs/layout.md`).
   */
  presentation?: 'auto' | 'popover'
  size?: 'sm' | 'md' | 'lg'
  /**
   * `null` is the empty choice, which is allowed only when `emptyOption` is set.
   */
  value?: string | null
}

/** Single-value choice from a closed list. */
export default function Select(given: SelectProps): JSX.Element {
  const props = mergeProps(
    { size: 'md', invalid: false, disabled: false, presentation: 'auto' } as Defaults<
      SelectProps,
      'size' | 'invalid' | 'disabled' | 'presentation'
    >,
    claimSlot(given),
  )
  return scope(() => {
    const uid = createUniqueId()
    const panel = elementRef<HTMLElement>()
    const scrim = elementRef<HTMLElement>()
    const sheetPanel = elementRef<HTMLElement>()
    const trigger = elementRef<HTMLElement>()
    const phone = useMediaQuery('phone')
    const sheeting = createDerived(() => props.presentation === 'auto' && phone())
    const emptyChoice = createDerived(() => ({
      value: '__polymorph-empty-choice__',
      label: props.emptyOption ?? '',
      description: undefined,
      disabled: false,
    }))
    const flat = createDerived(() => [
      ...(props.emptyOption === undefined ? [] : [emptyChoice.value]),
      ...props.options.flatMap((entry) => ('options' in entry ? entry.options : [entry])),
    ])
    const documentDirection = useDirection(() => trigger.value)
    const service = useMachine(
      zag.machine,
      () =>
        ({
          id: uid,
          dir: documentDirection(),
          collection: zag.collection({
            items: flat.value,
            itemToValue: (item) => item.value,
            itemToString: (item) => item.label,
            isItemDisabled: (item) => item.disabled === true,
          }),
          value:
            props.value === undefined
              ? undefined
              : props.value === null
                ? props.emptyOption === undefined
                  ? []
                  : ['__polymorph-empty-choice__']
                : [props.value],
          defaultValue:
            props.defaultValue === undefined && props.emptyOption !== undefined
              ? ['__polymorph-empty-choice__']
              : props.defaultValue === undefined
                ? undefined
                : props.defaultValue === null
                  ? props.emptyOption === undefined
                    ? []
                    : ['__polymorph-empty-choice__']
                  : [props.defaultValue],
          defaultOpen: props.defaultOpen,
          disabled: props.disabled,
          invalid: props.invalid,
          positioning: { placement: 'bottom-start' as const, gutter: 2 },
          ids: props.id === undefined ? undefined : { trigger: props.id },
          onValueChange: (details) => {
            props.onChange?.(
              details.value[0] === undefined || details.value[0] === '__polymorph-empty-choice__'
                ? null
                : details.value[0],
            )
          },
        }) as Partial<zag.Props>,
    )
    const api = createDerived(() => zag.connect(service, normalizeProps))
    const shown = createDerived(() =>
      flat.value.find((choice) => api.value.value.includes(choice.value)),
    )
    const placeholderShown = createDerived(() => shown.value === undefined)
    const present = usePresence(
      () => api.value.open && !sheeting.value,
      () => panel.value,
    )
    const sheetPresent = usePresence(
      () => api.value.open && sheeting.value,
      () => sheetPanel.value,
      'sheet.panel',
      { sheetSide: 'bottom' },
    )
    const scrimPresent = usePresence(
      () => api.value.open && sheeting.value,
      () => scrim.value,
      'dialog.scrim',
    )
    const effect1 = () => {
      void (
        api.value.open &&
        api.value.highlightedValue === null &&
        api.value.setHighlightValue(
          api.value.value[0] ?? flat.value.find((choice) => !choice.disabled)?.value ?? '',
        )
      )
    }
    watchEffect(
      createMemo(() => api.value.open),
      effect1,
      true,
    )
    const effect2 = () => {
      void (api.value.open || returnFocus(trigger.value, panel.value))
    }
    watchEffect(
      createMemo(() => api.value.open),
      effect2,
      false,
    )
    const effect3 = () => {
      followHighlight(panel.value, api.value.highlightedValue)
    }
    watchEffect(
      createMemo(() => api.value.highlightedValue),
      effect3,
      true,
    )
    let release4: (() => void) | undefined
    const effect4 = () => {
      release4?.()
      const ran = agentMember({
        member: 'Select',
        element: () => trigger.value,
        state: () => ({
          value:
            api.value.value[0] === undefined
              ? props.emptyOption === undefined
                ? null
                : ''
              : api.value.value[0] === '__polymorph-empty-choice__'
                ? ''
                : api.value.value[0],
          options: flat.value.map((choice) => ({
            id: choice.value === '__polymorph-empty-choice__' ? '' : choice.value,
            label: choice.label,
            ...(choice.disabled === true ? { disabled: true } : {}),
          })),
          open: api.value.open,
          disabled: props.disabled,
        }),
        actions: {
          choose: {
            argument: 'id',
            run: (value) =>
              api.value.setValue([value === '' ? '__polymorph-empty-choice__' : value]),
          },
          open: () => api.value.setOpen(true),
          close: () => api.value.setOpen(false),
        },
      })
      release4 = () => {
        ran()
      }
    }
    onMount(effect4)
    onCleanup(() => release4?.())
    return (
      <>
        {/* trigger */}
        <button
          {...mergeParts(api.value.getTriggerProps(), {
            class: styles.trigger,
            'aria-label': props['aria-label'],
            'aria-labelledby': props['aria-labelledby'],
            'aria-describedby': props['aria-describedby'],
            'aria-required': props['aria-required'],
            'aria-invalid': props.invalid ? true : undefined,
            'data-size': props.size,
            'data-invalid': props.invalid ? '' : undefined,
            'data-disabled': props.disabled ? '' : undefined,
            'data-placeholder': placeholderShown.value ? '' : undefined,
            'data-member': 'select',
          })}
          ref={trigger.attach}
        >
          <span class={styles.value}>
            {shown.value?.label ??
              (props.emptyOption === undefined ? (props.placeholder ?? '') : '')}
          </span>
          <span class={styles.chevron} aria-hidden="true">
            <Icon name="expand" size={props.size} />
          </span>
        </button>
        {props.name !== undefined ? (
          <input
            type="hidden"
            name={props.name}
            value={
              api.value.value[0] === undefined ||
              api.value.value[0] === '__polymorph-empty-choice__'
                ? ''
                : api.value.value[0]
            }
            disabled={props.disabled || undefined}
          />
        ) : null}
        <Portal>
          {afresh(() => (
            <>
              {present() ? (
                <div {...mergeParts(api.value.getPositionerProps())}>
                  {/* panel */}
                  <div
                    {...mergeParts(api.value.getContentProps(), {
                      class: styles.content,
                      style: {
                        '--radix-select-trigger-width': 'var(--reference-width)',
                        '--radix-select-content-available-height': 'var(--available-height)',
                        '--radix-select-content-transform-origin': 'var(--transform-origin)',
                      },
                      hidden: undefined,
                      'data-size': props.size,
                      'data-member': 'select',
                      onfocus: () => followHighlight(panel.value, api.value.highlightedValue),
                    })}
                    ref={panel.attach}
                  >
                    <div class={styles.viewport}>
                      {props.emptyOption !== undefined ? (
                        <div
                          {...mergeParts(api.value.getItemProps({ item: emptyChoice.value }), {
                            class: styles.item,
                            tabindex: '-1',
                            onfocus: () => api.value.setHighlightValue(emptyChoice.value.value),
                          })}
                        >
                          <span class={styles.check}>
                            {api.value.value.includes(emptyChoice.value.value) ? (
                              <Icon name="confirm" size="sm" />
                            ) : null}
                          </span>
                          <span class={styles.text}>
                            <span>{emptyChoice.value.label}</span>
                            {emptyChoice.value.description !== undefined ? (
                              <span class={styles.description}>
                                {emptyChoice.value.description}
                              </span>
                            ) : null}
                          </span>
                        </div>
                      ) : null}
                      <Each
                        of={props.options}
                        by={(entry) => ('options' in entry ? `group-${entry.label}` : entry.value)}
                        renew
                      >
                        {(entry) => (
                          <>
                            {'options' in entry ? (
                              <div
                                {...mergeParts(api.value.getItemGroupProps({ id: entry.label }), {
                                  class: styles.group,
                                })}
                              >
                                <div
                                  {...mergeParts(
                                    api.value.getItemGroupLabelProps({ htmlFor: entry.label }),
                                    { class: styles.groupLabel },
                                  )}
                                >
                                  {entry.label}
                                </div>
                                <Each of={entry.options} by={(choice) => choice.value} renew>
                                  {(choice) => (
                                    <div
                                      {...mergeParts(api.value.getItemProps({ item: choice }), {
                                        class: styles.item,
                                        tabindex: '-1',
                                        onfocus: () => api.value.setHighlightValue(choice.value),
                                      })}
                                    >
                                      <span class={styles.check}>
                                        {api.value.value.includes(choice.value) ? (
                                          <Icon name="confirm" size="sm" />
                                        ) : null}
                                      </span>
                                      <span class={styles.text}>
                                        <span>{choice.label}</span>
                                        {choice.description !== undefined ? (
                                          <span class={styles.description}>
                                            {choice.description}
                                          </span>
                                        ) : null}
                                      </span>
                                    </div>
                                  )}
                                </Each>
                              </div>
                            ) : (
                              <div
                                {...mergeParts(api.value.getItemProps({ item: entry }), {
                                  class: styles.item,
                                  tabindex: '-1',
                                  onfocus: () => api.value.setHighlightValue(entry.value),
                                })}
                              >
                                <span class={styles.check}>
                                  {api.value.value.includes(entry.value) ? (
                                    <Icon name="confirm" size="sm" />
                                  ) : null}
                                </span>
                                <span class={styles.text}>
                                  <span>{entry.label}</span>
                                  {entry.description !== undefined ? (
                                    <span class={styles.description}>{entry.description}</span>
                                  ) : null}
                                </span>
                              </div>
                            )}
                          </>
                        )}
                      </Each>
                    </div>
                  </div>
                </div>
              ) : null}
              {scrimPresent() ? (
                <div
                  class={sheet.scrim}
                  data-state={api.value.open ? 'open' : 'closed'}
                  ref={scrim.attach}
                />
              ) : null}
              {sheetPresent() ? (
                <div class={sheet.positioner}>
                  <div
                    class={sheet.panel}
                    data-presentation="sheet"
                    data-state={api.value.open ? 'open' : 'closed'}
                    tabindex="-1"
                    ref={sheetPanel.attach}
                  >
                    {/* panel */}
                    <div
                      {...mergeParts(api.value.getContentProps(), {
                        class: styles.sheetList,
                        hidden: undefined,
                        'data-size': props.size,
                        'data-member': 'select',
                        onfocus: () => followHighlight(panel.value, api.value.highlightedValue),
                      })}
                      ref={panel.attach}
                    >
                      {props.emptyOption !== undefined ? (
                        <div
                          {...mergeParts(api.value.getItemProps({ item: emptyChoice.value }), {
                            class: styles.item,
                            tabindex: '-1',
                            onfocus: () => api.value.setHighlightValue(emptyChoice.value.value),
                          })}
                        >
                          <span class={styles.check}>
                            {api.value.value.includes(emptyChoice.value.value) ? (
                              <Icon name="confirm" size="sm" />
                            ) : null}
                          </span>
                          <span class={styles.text}>
                            <span>{emptyChoice.value.label}</span>
                            {emptyChoice.value.description !== undefined ? (
                              <span class={styles.description}>
                                {emptyChoice.value.description}
                              </span>
                            ) : null}
                          </span>
                        </div>
                      ) : null}
                      <Each
                        of={props.options}
                        by={(entry) => ('options' in entry ? `group-${entry.label}` : entry.value)}
                        renew
                      >
                        {(entry) => (
                          <>
                            {'options' in entry ? (
                              <div
                                {...mergeParts(api.value.getItemGroupProps({ id: entry.label }), {
                                  class: styles.group,
                                })}
                              >
                                <div
                                  {...mergeParts(
                                    api.value.getItemGroupLabelProps({ htmlFor: entry.label }),
                                    { class: styles.groupLabel },
                                  )}
                                >
                                  {entry.label}
                                </div>
                                <Each of={entry.options} by={(choice) => choice.value} renew>
                                  {(choice) => (
                                    <div
                                      {...mergeParts(api.value.getItemProps({ item: choice }), {
                                        class: styles.item,
                                        tabindex: '-1',
                                        onfocus: () => api.value.setHighlightValue(choice.value),
                                      })}
                                    >
                                      <span class={styles.check}>
                                        {api.value.value.includes(choice.value) ? (
                                          <Icon name="confirm" size="sm" />
                                        ) : null}
                                      </span>
                                      <span class={styles.text}>
                                        <span>{choice.label}</span>
                                        {choice.description !== undefined ? (
                                          <span class={styles.description}>
                                            {choice.description}
                                          </span>
                                        ) : null}
                                      </span>
                                    </div>
                                  )}
                                </Each>
                              </div>
                            ) : (
                              <div
                                {...mergeParts(api.value.getItemProps({ item: entry }), {
                                  class: styles.item,
                                  tabindex: '-1',
                                  onfocus: () => api.value.setHighlightValue(entry.value),
                                })}
                              >
                                <span class={styles.check}>
                                  {api.value.value.includes(entry.value) ? (
                                    <Icon name="confirm" size="sm" />
                                  ) : null}
                                </span>
                                <span class={styles.text}>
                                  <span>{entry.label}</span>
                                  {entry.description !== undefined ? (
                                    <span class={styles.description}>{entry.description}</span>
                                  ) : null}
                                </span>
                              </div>
                            )}
                          </>
                        )}
                      </Each>
                    </div>
                  </div>
                </div>
              ) : null}
            </>
          ))}
        </Portal>
      </>
    )
  })
}
